#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int station;
    int type;
    int edge;
    int side;
} Endpoint;

typedef struct {
    long long distance;
    int node;
} HeapItem;

static int compare_endpoints(const void *a, const void *b) {
    const Endpoint *x = (const Endpoint *)a;
    const Endpoint *y = (const Endpoint *)b;

    if (x->station != y->station)
        return (x->station > y->station) - (x->station < y->station);
    if (x->type != y->type)
        return (x->type > y->type) - (x->type < y->type);
    if (x->edge != y->edge)
        return (x->edge > y->edge) - (x->edge < y->edge);
    return (x->side > y->side) - (x->side < y->side);
}

static int find_root(int *parent, int x) {
    int root = x;
    while (parent[root] != root)
        root = parent[root];

    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

static void unite(int *parent, int *size, int a, int b) {
    a = find_root(parent, a);
    b = find_root(parent, b);
    if (a == b)
        return;

    if (size[a] < size[b]) {
        int temp = a;
        a = b;
        b = temp;
    }
    parent[b] = a;
    size[a] += size[b];
}

static void heap_push(HeapItem **heap, int *size, int *capacity,
                      long long distance, int node) {
    if (*size == *capacity) {
        *capacity *= 2;
        *heap = (HeapItem *)realloc(*heap, (size_t)*capacity * sizeof(HeapItem));
    }

    int i = (*size)++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if ((*heap)[parent].distance <= distance)
            break;
        (*heap)[i] = (*heap)[parent];
        i = parent;
    }
    (*heap)[i].distance = distance;
    (*heap)[i].node = node;
}

static HeapItem heap_pop(HeapItem *heap, int *size) {
    HeapItem result = heap[0];
    HeapItem last = heap[--(*size)];

    if (*size > 0) {
        int i = 0;
        while (2 * i + 1 < *size) {
            int child = 2 * i + 1;
            if (child + 1 < *size &&
                heap[child + 1].distance < heap[child].distance)
                child++;

            if (heap[child].distance >= last.distance)
                break;

            heap[i] = heap[child];
            i = child;
        }
        heap[i] = last;
